from flask import Flask, jsonify, abort
app = Flask(__name__)
DOCUMENTS = {1: {"title": "Secret", "owner": "alice"}}

@app.route("/documents/<int:doc_id>")
def read_doc(doc_id):
    doc = DOCUMENTS.get(doc_id)
    owner = doc.get("owner")
    current_user = "alice"
    if owner != current_user:
        abort(403)
    return jsonify(doc)

